package dispatch

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// requireSecureDispatchURL is the secure-base-URL guard used before the cloud
// client sends a bearer token. Tests swap it to allow httptest.NewServer
// (http://127.0.0.1:...) endpoints; production always routes through
// api.RequireSecureURL and rejects plain HTTP.
var requireSecureDispatchURL = api.RequireSecureURL

func runServer(ctx context.Context, opts Options) (*Dispatch, error) {
	baseURL := api.BaseURL()
	if opts.InsecureHTTPAuth {
		auth.EnableInsecureHTTP()
	} else {
		if err := requireSecureDispatchURL(baseURL); err != nil {
			return nil, fmt.Errorf("dispatch base URL: %w", err)
		}
	}

	// Resolve a bearer scoped to the dispatch service host. In split-host
	// deployments the tokenmanager runs an RFC 8693 exchange so the
	// bearer carries the data-API audience rather than the auth-host
	// one; single-host setups hit the same-host shortcut and return the
	// core token unchanged. OriginOnly strips any path the operator may
	// have included in ENTIRE_API_BASE_URL — tokenmanager validates
	// Resource as a strict origin URL.
	token, err := lookupResourceToken(ctx, api.OriginOnly(baseURL))
	if errors.Is(err, auth.ErrNotLoggedIn) {
		return nil, errors.New("dispatch requires login — run `entire login`")
	}
	if err != nil {
		return nil, fmt.Errorf("reading credentials: %w", err)
	}

	now := nowUTC()
	sinceInput := strings.TrimSpace(opts.Since)
	if sinceInput == "" {
		sinceInput = "7d"
	}
	since, err := ParseSinceAtNow(sinceInput, now)
	if err != nil {
		return nil, err
	}
	until, err := ParseUntilAtNow(opts.Until, now)
	if err != nil {
		return nil, err
	}
	normalizedSince, normalizedUntil := NormalizeWindow(since, until)
	if !normalizedSince.Before(normalizedUntil) {
		return nil, errors.New("--since must be before --until")
	}

	repos := append([]string(nil), opts.RepoPaths...)
	if len(repos) == 0 {
		repoRoot, err := paths.WorktreeRoot(ctx)
		if err != nil {
			return nil, fmt.Errorf("not in a git repository: %w", err)
		}
		repo, err := gitrepo.OpenPath(repoRoot)
		if err != nil {
			return nil, fmt.Errorf("open repository: %w", err)
		}
		defer repo.Close()

		repoFullName, err := resolveRepoFullName(ctx, repo)
		if err != nil {
			return nil, err
		}
		repos = []string{repoFullName}
	}

	cloud := NewCloudClient(CloudConfig{BaseURL: baseURL, Token: token})
	reqBody := CreateDispatchRequest{
		Repos:    repos,
		Since:    normalizedSince.Format(time.RFC3339),
		Until:    normalizedUntil.Format(time.RFC3339),
		Generate: true,
		Voice:    resolvedDispatchVoicePreference(opts.Voice),
	}
	response, err := cloud.CreateDispatch(ctx, reqBody)
	if err != nil {
		return nil, err
	}

	dispatch := apiToDispatch(response)
	if strings.TrimSpace(dispatch.GeneratedText) == "" {
		return nil, errDispatchMissingMarkdown
	}
	return dispatch, nil
}

func apiToDispatch(response *CreateDispatchResponse) *Dispatch {
	if response == nil {
		return &Dispatch{}
	}

	repos := make([]RepoGroup, 0, len(response.Repos))
	for _, repo := range response.Repos {
		sections := make([]Section, 0, len(repo.Sections))
		for _, section := range repo.Sections {
			bullets := make([]Bullet, 0, len(section.Bullets))
			for _, bullet := range section.Bullets {
				bullets = append(bullets, Bullet{
					CheckpointID: bullet.CheckpointID,
					Text:         bullet.Text,
					Source:       bullet.Source,
					Branch:       bullet.Branch,
					CreatedAt:    parseAPITime(bullet.CreatedAt),
					Labels:       append([]string(nil), bullet.Labels...),
				})
			}
			sections = append(sections, Section{
				Label:   section.Label,
				Bullets: bullets,
			})
		}
		repos = append(repos, RepoGroup{
			FullName: repo.FullName,
			URL:      githubRepoURL(repo.FullName),
			Sections: sections,
		})
	}

	generatedText := strings.TrimSpace(response.GeneratedMarkdown)
	if generatedText == "" {
		generatedText = strings.TrimSpace(response.GeneratedText)
	}

	return &Dispatch{
		Window: Window{
			NormalizedSince:   parseAPITime(response.Window.NormalizedSince),
			NormalizedUntil:   parseAPITime(response.Window.NormalizedUntil),
			FirstCheckpointAt: parseAPITime(response.Window.FirstCheckpointCreatedAt),
			LastCheckpointAt:  parseAPITime(response.Window.LastCheckpointCreatedAt),
		},
		CoveredRepos:  append([]string(nil), response.CoveredRepos...),
		Repos:         repos,
		GeneratedText: generatedText,
	}
}

func parseAPITime(value string) time.Time {
	if value == "" {
		return time.Time{}
	}
	parsed, err := time.Parse(time.RFC3339, value)
	if err != nil {
		return time.Time{}
	}
	return parsed
}

package dispatch

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"time"
)

var (
	goDurationPattern  = regexp.MustCompile(`^(\d+)([smhdw])$`)
	relativePattern    = regexp.MustCompile(`^(\d+)\s*(second|minute|hour|day|week|month)s?(?:\s*ago)?$`)
	lastWeekdayPattern = regexp.MustCompile(`^last\s+(monday|tuesday|wednesday|thursday|friday|saturday|sunday)$`)
)

// ParseSinceAtNow parses durations like 7d, relative times like "2 days ago",
// RFC3339 timestamps, and ISO dates.
func ParseSinceAtNow(value string, now time.Time) (time.Time, error) {
	parsed, err := parseTimeAtNow(value, now)
	if err != nil {
		return time.Time{}, err
	}
	if parsed.IsZero() {
		return time.Time{}, fmt.Errorf("unparseable --since: %q", strings.TrimSpace(value))
	}
	return parsed, nil
}

func ParseUntilAtNow(value string, now time.Time) (time.Time, error) {
	parsed, err := parseTimeAtNow(value, now)
	if err != nil {
		return time.Time{}, err
	}
	if parsed.IsZero() {
		return now, nil
	}
	return parsed, nil
}

func parseTimeAtNow(value string, now time.Time) (time.Time, error) {
	value = strings.TrimSpace(value)
	if value == "" {
		return time.Time{}, nil
	}
	if strings.EqualFold(value, "now") {
		return now, nil
	}

	if matches := goDurationPattern.FindStringSubmatch(value); matches != nil {
		n, err := strconv.Atoi(matches[1])
		if err != nil {
			return time.Time{}, fmt.Errorf("parse duration count: %w", err)
		}
		switch matches[2] {
		case "d":
			return now.Add(-time.Duration(n) * 24 * time.Hour), nil
		case "w":
			return now.Add(-time.Duration(n) * 7 * 24 * time.Hour), nil
		default:
			d, err := time.ParseDuration(matches[1] + matches[2])
			if err != nil {
				return time.Time{}, fmt.Errorf("parse duration: %w", err)
			}
			return now.Add(-d), nil
		}
	}

	if matches := relativePattern.FindStringSubmatch(strings.ToLower(value)); matches != nil {
		n, err := strconv.Atoi(matches[1])
		if err != nil {
			return time.Time{}, fmt.Errorf("parse relative count: %w", err)
		}
		var unit time.Duration
		switch matches[2] {
		case "second":
			unit = time.Second
		case "minute":
			unit = time.Minute
		case "hour":
			unit = time.Hour
		case "day":
			unit = 24 * time.Hour
		case "week":
			unit = 7 * 24 * time.Hour
		case "month":
			unit = 30 * 24 * time.Hour
		}
		return now.Add(-time.Duration(n) * unit), nil
	}

	if matches := lastWeekdayPattern.FindStringSubmatch(strings.ToLower(value)); matches != nil {
		target := weekdayFromString(matches[1])
		if target >= 0 {
			diff := (int(now.Weekday()) - int(target) + 7) % 7
			if diff == 0 {
				diff = 7
			}
			return now.Add(-time.Duration(diff) * 24 * time.Hour), nil
		}
	}

	if parsed, err := time.Parse(time.RFC3339, value); err == nil {
		return parsed, nil
	}
	if parsed, err := time.Parse("2006-01-02", value); err == nil {
		return parsed, nil
	}

	return time.Time{}, fmt.Errorf("unparseable time: %q", value)
}

func weekdayFromString(value string) time.Weekday {
	switch value {
	case "sunday":
		return time.Sunday
	case "monday":
		return time.Monday
	case "tuesday":
		return time.Tuesday
	case "wednesday":
		return time.Wednesday
	case "thursday":
		return time.Thursday
	case "friday":
		return time.Friday
	case "saturday":
		return time.Saturday
	default:
		return -1
	}
}
package dispatch

import (
	"errors"
	"fmt"
	"regexp"
	"strings"
)

var githubRepoSlugPattern = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]*/[A-Za-z0-9._-]+$`)

func ResolveOptions(
	flagLocal bool,
	flagSince string,
	flagUntil string,
	flagAllBranches bool,
	flagRepos []string,
	flagVoice string,
	flagInsecureHTTPAuth bool,
	currentBranch func() (string, error),
) (Options, error) {
	flagRepos = normalizeScopeValues(flagRepos)

	if flagLocal && len(flagRepos) > 0 {
		return Options{}, errors.New("--repos cannot be used with --local")
	}
	if !flagLocal && flagAllBranches {
		return Options{}, errors.New("--all-branches only applies to --local (cloud dispatch uses each repo's default branch)")
	}
	if !flagLocal {
		if err := validateRepoSlugs(flagRepos); err != nil {
			return Options{}, err
		}
	}
	if !flagLocal && len(flagRepos) > CloudRepoLimit {
		return Options{}, fmt.Errorf("--repos supports at most %d repos per dispatch", CloudRepoLimit)
	}

	mode := ModeServer
	if flagLocal {
		mode = ModeLocal
	}

	var branches []string
	implicitCurrentBranch := false
	if flagLocal && !flagAllBranches {
		currentBranchName, err := currentBranch()
		if err != nil {
			return Options{}, err
		}
		branches = []string{currentBranchName}
		implicitCurrentBranch = true
	}

	return Options{
		Mode:                  mode,
		RepoPaths:             flagRepos,
		Since:                 flagSince,
		Until:                 flagUntil,
		Branches:              branches,
		AllBranches:           flagAllBranches,
		ImplicitCurrentBranch: implicitCurrentBranch,
		Voice:                 flagVoice,
		InsecureHTTPAuth:      flagInsecureHTTPAuth,
	}, nil
}

func normalizeScopeValues(values []string) []string {
	normalized := make([]string, 0, len(values))
	seen := make(map[string]struct{}, len(values))
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value == "" {
			continue
		}
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		normalized = append(normalized, value)
	}
	return normalized
}

func validateRepoSlugs(values []string) error {
	for _, value := range values {
		if !githubRepoSlugPattern.MatchString(value) {
			return fmt.Errorf("invalid repo %q: expected owner/repo", value)
		}
	}
	return nil
}
