	loadRepos := newLazyOptions(func() []huh.Option[string] {
		slugs, listErr := listDispatchWizardRepos(ctx)
		if listErr != nil || len(slugs) == 0 {
			slugs = discoverLocalRepoSlugs(ctx, currentRepo)
		}
		return buildDispatchRepoOptions(slugs)
	})
