// Walk every page of the caller's federated repos index and return all rows.
// Used when a selection includes a bare ULID (core's full_name filter can't
// surface it) and by the view-auth ULID set — both need the complete set, since
// a repo on a later page would otherwise be missed.
// Hard ceiling on index pages walked — a backstop against a core that echoes a
// non-empty token forever. At core's page sizes this is far more repos than any
// real caller has; hitting it means something is wrong upstream, so stop.
const MAX_INDEX_PAGES = 100

async function listAllIndexRepos(
  coreBaseUrl: string,
  loginJwt: string,
  fetchTimeoutMs: number | undefined,
): Promise<ReposIndexRow[]> {
  const rows: ReposIndexRow[] = []
  const seenTokens = new Set<string>()
  let pageToken: string | undefined
  for (let i = 0; i < MAX_INDEX_PAGES; i++) {
    const page = await listReposIndex({ coreBaseUrl, loginJwt, pageToken, fetchTimeoutMs })
    rows.push(...page.repos)
    const next = page.nextPageToken || undefined
    // Stop on a terminal page OR a token that doesn't advance (a stale/echoed
    // token would otherwise loop forever).
    if (!next || seenTokens.has(next)) break
    seenTokens.add(next)
    pageToken = next
  }
  return rows
}

function unroutedResponse(unrouted: string[]): Response {
  // Atomic fail: a single dispatch is one LLM call over all selected repos, so a
  // repo with no routable placement must fail the whole request rather than
  // silently drop out of the recap.
  return errorResponse(
    404,
    `Repository not found or not available in its region: ${unrouted.join(", ")}`,
  )
}

/**
 * Resolve the selected repos and collect their checkpoint data from the cells.
 * Atomic-fails (404) on any unrouted repo and (502) on any cell read error.
 * The record is `null` only when no repos are covered (route maps that to 404).
 * Session callers fan out across jurisdictions via the core index; bearer/CLI
 * callers read from their home cell.
 */
export async function resolveAndCollectDispatch(
  c: Context<{ Bindings: Env; Variables: Variables }>,
  body: CreateDispatchRequest,
): Promise<ResolveDispatchOutcome> {
  const bearerToken = bearerTokenFromAuthorization(c.req.header("Authorization"))

  if (bearerToken) {
    return resolveViaHomeCell(c, body, bearerToken)
  }
  return resolveViaCoreIndex(c, body)
}

// Browser-session path: login JWT → federated core index → per-cell fan-out.
async function resolveViaCoreIndex(
  c: Context<{ Bindings: Env; Variables: Variables }>,
  body: CreateDispatchRequest,
): Promise<ResolveDispatchOutcome> {
  const baseUrlTemplate = c.env.ENTIRE_API_BASE_URL_TEMPLATE
  const coreConfig = getCoreAuthConfig(c.env)
  if (!coreConfig || !baseUrlTemplate) {
    return { kind: "error", response: errorResponse(503, "Dispatch generation unavailable") }
  }

  const sessionToken = getCookie(c, "session") ?? null
  if (!sessionToken) {
    return { kind: "error", response: errorResponse(401, "Not authenticated") }
  }

  const cfg = coreClientConfigFromAuth(coreConfig)
  const loginResult = await getValidLoginJwt(
    { kv: c.env.ENTIRE_CACHE, secret: c.env.ENCRYPTION_KEY, cfg },
    sessionToken,
  )
  if (loginResult.kind !== "jwt") {
    return { kind: "error", response: errorResponse(401, "Not authenticated") }
  }
  const loginJwt = loginResult.jwt
  const coreBaseUrl = resolveCoreBaseUrlForLoginJwt(cfg, loginJwt)

  // Resolve each selected repo with an EXACT filtered index lookup rather than a
  // single default page: core answers a `filter=owner/repo` request directly from
  // the registry (zero-or-one rows, `truncated` always false), so a repo beyond
  // the caller's first index page still resolves. A bare (unfiltered) page could
  // omit it and falsely 404. Mirrors proxy.ts's resolveViaIndex.
  //
  // Core's filter exact-matches `full_name`, so feed it the normalized slug
  // (`gh/` stripped, lowercased) — a raw `gh/owner/repo` selection would
  // otherwise match nothing and falsely 404. resolveDispatchRepos then re-matches
  // the returned rows against the ORIGINAL slug via matchRepoInIndex.
  //
  // A bare repo ULID has no `full_name` for the filter to match, so if any
  // selected slug is a bare id (no `/`), page the caller's full accessible index
  // once and match locally (matchRepoInIndex resolves a ULID against `id`). The
  // common all-slug case keeps the cheap per-slug exact filtered lookups.
  const scopeRepos = normalizeScopeValues(body.repos)
  const hasBareUlid = scopeRepos.some((slug) => !normalizeRepoSlug(slug).includes("/"))
  let indexRows: ReposIndexRow[]
  try {
    if (hasBareUlid) {
      indexRows = await listAllIndexRepos(coreBaseUrl, loginJwt, cfg.fetchTimeoutMs)
    } else {
      const pages = await Promise.all(
        scopeRepos.map((slug) =>
          listReposIndex({
            coreBaseUrl,
            loginJwt,
            filter: normalizeRepoSlug(slug),
            fetchTimeoutMs: cfg.fetchTimeoutMs,
          }),
        ),
      )
      // A filtered lookup is exact; a truncated page means the core ignored the
      // (to it unknown) filter param — a lagging deploy — so a miss would prove
      // nothing. Fail loudly rather than fold it into a bogus 404.
      if (pages.some((page) => page.truncated)) {
        throw new Error("filtered repos index lookup returned a truncated page (core too old?)")
      }
      indexRows = pages.flatMap((page) => page.repos)
    }
  } catch {
    return { kind: "error", response: errorResponse(502, "Could not list repositories") }
  }

  const { resolved, unrouted } = resolveDispatchRepos(indexRows, scopeRepos)
  if (unrouted.length > 0) {
    return { kind: "error", response: unroutedResponse(unrouted) }
  }

  const reader = createEntireApiCheckpointReader({
    baseUrlTemplate,
    loginJwt,
  })

  return collect(body, resolved, reader)
}

// Bearer/CLI path: resolve + read against the caller's home cell.
async function resolveViaHomeCell(
  c: Context<{ Bindings: Env; Variables: Variables }>,
  body: CreateDispatchRequest,
  bearerToken: string,
): Promise<ResolveDispatchOutcome> {
  if (!isEntireApiHomeConfigured(c.env)) {
    return { kind: "error", response: errorResponse(503, "Dispatch generation unavailable") }
  }

  const deps = buildEntireApiDeps(c)
  const userAgent = c.req.header("User-Agent") ?? undefined

  let homeRepos
  try {
    homeRepos = await listHomeRepos({ deps, bearerToken, userAgent })
  } catch {
    return { kind: "error", response: errorResponse(502, "Could not list repositories") }
  }

  // Match each selected slug against the home listing: a `gh/owner/repo` /
  // `owner/repo` slug matches full_name case-insensitively (same rule as the
  // index's matchRepoInIndex); a bare ULID matches id.
  const byName = new Map(homeRepos.map((repo) => [repo.full_name.toLowerCase(), repo]))
  const byId = new Map(homeRepos.map((repo) => [repo.id, repo]))
  const scopeRepos = normalizeScopeValues(body.repos)
  const resolved: ResolvedDispatchRepo[] = []
  const unrouted: string[] = []
  const defaultBranchByUlid = new Map<string, string>()
  // Collapse alias slugs (gh/ prefix, case, ULID vs full_name) that resolve to
  // the same repo, so it isn't read or counted twice.
  const seen = new Set<string>()

  for (const slug of scopeRepos) {
    const item = byName.get(normalizeRepoSlug(slug)) ?? byId.get(slug)
    if (!item) {
      unrouted.push(slug)
      continue
    }
    if (seen.has(item.id)) continue
    seen.add(item.id)
    resolved.push({
      slug,
      fullName: item.full_name,
      repoUlid: item.id,
      // Home path reads via proxyEntireApiHome (home jurisdiction), so the cell
      // isn't addressed by name here — placeholders keep the shared shape.
      cell: "home",
      jurisdiction: "home",
    })
    defaultBranchByUlid.set(item.id, item.default_branch || "main")
  }

  if (unrouted.length > 0) {
    return { kind: "error", response: unroutedResponse(unrouted) }
  }

  const reader = createHomeEntireApiCheckpointReader({
    deps,
    bearerToken,
    defaultBranchByUlid,
    userAgent,
  })

  return collect(body, resolved, reader)
}

async function collect(
  body: CreateDispatchRequest,
  resolved: ResolvedDispatchRepo[],
  reader: Parameters<typeof buildDispatchDetailViaFanout>[2],
): Promise<ResolveDispatchOutcome> {
  let record: DispatchDetail | null
  try {
    record = await buildDispatchDetailViaFanout(body, resolved, reader)
  } catch (err) {
    console.error("[dispatch] cell fan-out read failed", err)
    return {
      kind: "error",
      response: errorResponse(502, "Failed to read dispatch data from a repository's region"),
    }
  }
  return {
    kind: "ok",
    record,
    scopeRepos: resolved.map((r) => r.fullName),
    scopeRepoUlids: resolved.map((r) => r.repoUlid),
  }
}
