+function withJurisdiction<T extends { jurisdiction?: string }>(row: T, jurisdiction?: string): T {
+  // A malformed/bodyless response flows through so the caller's own shape
+  // check produces the legible error, rather than a TypeError here.
+  if (!row || typeof row !== "object") return row
