// Empty slices rather than nil: a null reads as "unknown", not "none".
func dispatchReposWire(groups []dispatch.RepoGroup) []DispatchRepoGroupWire {
	out := make([]DispatchRepoGroupWire, 0, len(groups))
	for _, g := range groups {
		sections := make([]DispatchSectionWire, 0, len(g.Sections))
		for _, sec := range g.Sections {
			bullets := make([]DispatchBulletWire, 0, len(sec.Bullets))
			for _, b := range sec.Bullets {
				bullets = append(bullets, DispatchBulletWire{
					CheckpointID: b.CheckpointID,
					Text:         b.Text,
					Source:       string(b.Source),
					Branch:       b.Branch,
					CreatedAt:    b.CreatedAt,
					Labels:       b.Labels,
				})
			}
			sections = append(sections, DispatchSectionWire{Label: sec.Label, Bullets: bullets})
		}
		out = append(out, DispatchRepoGroupWire{FullName: g.FullName, Sections: sections})
	}
	return out
}
