// Jurisdiction scoping for the dispatch form.
//
// A dispatch covers repos placed in exactly one jurisdiction and is generated
// and stored by that jurisdiction's cell. The form therefore asks for a
// jurisdiction first and offers only the repos placed there second, so a mixed
// selection cannot be expressed. Everything here is derived client-side from
// the jurisdiction-federated repo stream, whose rows already carry every
// placement with its jurisdiction and clone status — no extra request.

import type { ComboboxOption } from "@/components"
import type { RepositoryPlacement } from "@/data/repositories/repository"

/**
 * The slice of a repo row this module reads. `checkpoint_count` is repo-GLOBAL
 * (the stream has no per-placement count), so a ready mirror whose checkpoint
 * refs were never synced is still offered in its jurisdiction — the cell then
 * answers the POST with its own "repository not found"/empty-window error.
 * Known limitation until placements carry per-copy counts.
 */
export interface ScopedRepo {
  full_name: string
  checkpoint_count?: number | null
  placements?: RepositoryPlacement[]
}

/**
 * The jurisdictions a repo is placed in. A row that reports no placements
 * (an older stream shape, or a fixture) cannot be scoped and is attributed to
 * `fallback` — the caller's home jurisdiction — which is also where the
 * pre-picker gateway would have sent it. `fallback` may be "" (home unknown),
 * in which case such rows share one unscoped bucket.
 */
export function repoJurisdictions(repo: ScopedRepo, fallback: string): string[] {
  const placements = repo.placements ?? []
  if (placements.length === 0) return [fallback]
  return [...new Set(placements.map((p) => p.jurisdiction))]
}

function hasCheckpoints(repo: ScopedRepo): boolean {
  return (repo.checkpoint_count ?? 0) > 0
}

/** The repo's copies in one jurisdiction. */
function copiesIn(repo: ScopedRepo, jurisdiction: string): RepositoryPlacement[] {
  return (repo.placements ?? []).filter((p) => p.jurisdiction === jurisdiction)
}

// Still cloning. A jurisdiction with one ready copy and one still cloning is
// served by the ready copy, so only an all-processing jurisdiction counts.
function isSyncingIn(repo: ScopedRepo, jurisdiction: string): boolean {
  const copies = copiesIn(repo, jurisdiction)
  return copies.length > 0 && copies.every((p) => p.status === "processing")
}

// Excluded outright: every copy in the jurisdiction has terminally failed.
function isDeadIn(repo: ScopedRepo, jurisdiction: string): boolean {
  const copies = copiesIn(repo, jurisdiction)
  return copies.length > 0 && copies.every((p) => p.status === "failed" || p.status === "suspended")
}

// A repo is offered in a jurisdiction when it has checkpoints there or is
// still syncing there (shown disabled, so the user learns why it's missing
// rather than wondering). A dead placement is not offered at all.
function isOfferedIn(repo: ScopedRepo, jurisdiction: string, fallback: string): boolean {
  if (!repoJurisdictions(repo, fallback).includes(jurisdiction)) return false
  if (isDeadIn(repo, jurisdiction)) return false
  return hasCheckpoints(repo) || isSyncingIn(repo, jurisdiction)
}

/**
 * Jurisdictions the caller has at least one offerable repo in, sorted. The ""
 * bucket (placement-less rows with home unknown) is never offered: it isn't a
 * jurisdiction a user could pick — the picker then simply doesn't render and
 * the form falls back to the pre-picker unscoped behaviour.
 */
export function eligibleJurisdictions(repos: ScopedRepo[], fallback: string): string[] {
  const out = new Set<string>()
  for (const repo of repos) {
    for (const jurisdiction of repoJurisdictions(repo, fallback)) {
      if (jurisdiction !== "" && isOfferedIn(repo, jurisdiction, fallback)) out.add(jurisdiction)

