func dispatchGenerateAndPersist(ctx context.Context, deps *DispatchDeps, acc, runID string, detail *dispatch.Detail) {
	defer func() {
		if rec := recover(); rec != nil {
			slog.ErrorContext(ctx, "dispatch: generation panicked; recovered, run marked failed",
				slog.String("account_id", acc), slog.String("run_id", runID),
				slog.Any("panic", rec), slog.String("stack", string(debug.Stack())))
			failDispatchRun(ctx, deps, acc, runID, fmt.Sprintf("panic: %v", rec))
		}
	}()

	ctx = context.WithoutCancel(ctx)

	genCtx, cancel := context.WithTimeout(ctx, dispatchGenerationTimeout)
	defer cancel()
	markdown, genErr := deps.Generator.Generate(genCtx, ai.AnthropicSonnet46, ai.Options{
		System:    dispatch.SystemPrompt,
		User:      dispatch.BuildUserPrompt(*detail),
		MaxTokens: dispatchGenerationMaxTokens,
		Feature:   ai.FeatureDispatch,
	})

	if genErr != nil {
		slog.WarnContext(ctx, "dispatch: generation failed",
			slog.Any("error", genErr), slog.String("account_id", acc), slog.String("run_id", runID))
		failDispatchRun(ctx, deps, acc, runID, genErr.Error())
		return
	}

	persistCtx, persistCancel := context.WithTimeout(ctx, dispatchPersistTimeout)
	defer persistCancel()
	if _, found, err := deps.Store.CompleteDispatchRun(persistCtx, acc, runID, markdown); err != nil {
		slog.ErrorContext(persistCtx, "dispatch: complete dispatch run persist failed",
			slog.Any("error", err), slog.String("account_id", acc), slog.String("run_id", runID))
	} else if !found {
		slog.ErrorContext(persistCtx, "dispatch: complete dispatch run found no running run",
			slog.String("account_id", acc), slog.String("run_id", runID))
	}
}

func failDispatchRun(ctx context.Context, deps *DispatchDeps, acc, runID, reason string) {
	persistCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), dispatchPersistTimeout)
	defer cancel()
	if _, found, err := deps.Store.FailDispatchRun(persistCtx, acc, runID, reason); err != nil {
		slog.ErrorContext(persistCtx, "dispatch: fail dispatch run persist failed",
			slog.Any("error", err), slog.String("account_id", acc), slog.String("run_id", runID))
	} else if !found {
		slog.ErrorContext(persistCtx, "dispatch: fail dispatch run found no running run",
			slog.String("account_id", acc), slog.String("run_id", runID))
	}
}
