package dispatch

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
)

type CloudConfig struct {
	BaseURL string
	Token   string
	HTTP    *http.Client
	Timeout time.Duration
}

type CloudClient struct {
	baseURL string
	token   string
	http    *http.Client
}

const defaultCloudHTTPTimeout = 120 * time.Second

// The cell-backed dispatch surface (entire.io's /api/v1/me/dispatches). A
// dispatch covers repos placed in exactly one jurisdiction and is generated AND
// stored by that jurisdiction's entire-api cell — never the caller's home cell
// on their behalf. The gateway picks the cell from the `?jurisdiction=` query
// selector (gateway-only: validated and stripped before forwarding; the body
// never carries it). Omitted → the caller's home jurisdiction, so a CLI that
// sends nothing behaves exactly as before.
//
// The POST answers 202 with the run still generating; the CLI then polls the
// run by id, sending the SAME selector, because point-to-point responses are
// not stamped with the jurisdiction — the caller labels the row with the scope
// it requested with.
const (
	dispatchesPath = "/api/v1/me/dispatches"

	// jurisdictionQueryParam is the gateway-only routing selector.
	jurisdictionQueryParam = "jurisdiction"

	// DispatchStatusGenerating is a run the cell is still generating; poll.
	DispatchStatusGenerating = "generating"
	// DispatchStatusComplete is a run with its markdown persisted.
	DispatchStatusComplete = "complete"
	// DispatchStatusFailed is a run the cell gave up on (ErrorMessage says why).
	DispatchStatusFailed = "failed"
)

// dispatchPollInterval / dispatchPollTimeout bound the 202 poll loop. The
// cell's own generation ceiling is ~90s and it reports a run stuck longer than
// 2 minutes as failed, so the timeout sits just above that: past it the cell
// itself would already be saying "failed". Vars so tests can shrink them.
var (
	dispatchPollInterval = 2 * time.Second
	dispatchPollTimeout  = 3 * time.Minute
)

func NewCloudClient(cfg CloudConfig) *CloudClient {
	baseURL := cfg.BaseURL
	if baseURL == "" {
		baseURL = api.BaseURL()
	}

	httpClient := cfg.HTTP
	if httpClient == nil {
		timeout := cfg.Timeout
		if timeout <= 0 {
			timeout = defaultCloudHTTPTimeout
		}
		httpClient = &http.Client{Timeout: timeout}
	} else if cfg.Timeout > 0 && httpClient.Timeout == 0 {
		httpClient.Timeout = cfg.Timeout
	}

	return &CloudClient{
		baseURL: strings.TrimRight(baseURL, "/"),
		token:   cfg.Token,
		http:    httpClient,
	}
}

// CreateDispatchRequest is the cell's POST /me/dispatches body. There is
// deliberately no jurisdiction field — that is the gateway's query selector.
// Branches are omitted: cloud dispatch always covers each repo's default
// branch, which is what the cell does when the field is absent.
type CreateDispatchRequest struct {
	Repos []string `json:"repos,omitempty"`
	Since string   `json:"since"`
	Until string   `json:"until"`
	Voice string   `json:"voice,omitempty"`
}

// DispatchDetail mirrors entire-api's DispatchDetailWire (camelCase) — the
// shape both the POST and the by-id GET return. Only the fields the CLI reads
// are declared; unknown fields are ignored for forward compatibility.
type DispatchDetail struct {
	ID                string      `json:"id"`
	SetupID           string      `json:"setupId"`
	Status            string      `json:"status"`
	Title             *string     `json:"title"`
	CoveredRepos      []string    `json:"coveredRepos"`
	Branches          []string    `json:"branches"`
	Voice             *string     `json:"voice"`
	Window            APIWindow   `json:"window"`
	Totals            APITotals   `json:"totals"`
	Repos             []APIRepo   `json:"repos"`
	GeneratedMarkdown string      `json:"generatedMarkdown"`
	ErrorMessage      *string     `json:"errorMessage"`
	CreatedAt         string      `json:"createdAt"`
	CompletedAt       *string     `json:"completedAt"`
	Notices           []string    `json:"notices"`
	Raw               json.RawMessage `json:"-"`
}

type APIWindow struct {
	NormalizedSince          string  `json:"normalizedSince"`
	NormalizedUntil          string  `json:"normalizedUntil"`
	FirstCheckpointCreatedAt *string `json:"firstCheckpointCreatedAt"`
	LastCheckpointCreatedAt  *string `json:"lastCheckpointCreatedAt"`
}

type APIRepo struct {
	FullName string       `json:"fullName"`
	Sections []APISection `json:"sections"`
}

type APISection struct {
	Label   string      `json:"label"`
	Bullets []APIBullet `json:"bullets"`
}

type APIBullet struct {
	CheckpointID string   `json:"checkpointId"`
	Text         string   `json:"text"`
	Source       string   `json:"source"`
	Branch       string   `json:"branch"`
	CreatedAt    string   `json:"createdAt"`
	Labels       []string `json:"labels"`
}

type APITotals struct {
	Checkpoints         int `json:"checkpoints"`
	UsedCheckpointCount int `json:"usedCheckpointCount"`
	Branches            int `json:"branches"`
	FilesTouched        int `json:"filesTouched"`
}

// RepoNotFoundError is the cell's 404 for a repo that is not placed in (or
// not visible in) the jurisdiction the request was routed to. Jurisdiction is
// the selector the caller sent ("" = home); Repos are the slugs the cell named.
//
// This is the cross-jurisdiction failure the selector exists for: a repo
// mirrored only in US, requested from an AU home, is simply unknown to the AU
// cell. The message therefore says which jurisdiction was targeted and how to
// pick another, rather than reading like the repo does not exist at all.
type RepoNotFoundError struct {
	Jurisdiction string
	Repos        []string
	Message      string
}

const repoNotFoundPrefix = "repository not found"

func (e *RepoNotFoundError) Error() string {
	return fmt.Sprintf(
		"In %s: %s. Pick a jurisdiction the repository is mirrored into (entire dispatch --jurisdiction <slug>), or mirror it there.",
		e.ScopeLabel(), e.Message,
	)
}

// ScopeLabel names the jurisdiction the failed request targeted, the way the
// web app does ("US"), or the home default when none was selected.
func (e *RepoNotFoundError) ScopeLabel() string {
	if strings.TrimSpace(e.Jurisdiction) == "" {
		return "your home jurisdiction"
	}
	return strings.ToUpper(e.Jurisdiction)
}

// httpStatusError is a non-2xx answer with whatever message the body carried
// (gateway `{"error"}` or huma `{"detail"}` shape), so callers can branch on
// status without re-parsing.
type httpStatusError struct {
	status  int
	message string
	raw     string
}

func (e *httpStatusError) Error() string {
	if e.raw == "" {
		return fmt.Sprintf("dispatch service returned status %d", e.status)
	}
	return fmt.Sprintf("dispatch service returned status %d: %s", e.status, strconv.Quote(e.raw))
}

// CreateDispatch starts a dispatch in the cell of `jurisdiction` ("" = the
// caller's home). The returned detail is usually still generating — pass it to
// WaitForDispatch with the same jurisdiction.
func (c *CloudClient) CreateDispatch(ctx context.Context, reqBody CreateDispatchRequest, jurisdiction string) (*DispatchDetail, error) {
	var out DispatchDetail
	err := c.doJSON(ctx, http.MethodPost, dispatchesPath, jurisdictionQuery(jurisdiction), reqBody, &out)
	if err != nil {
		var statusErr *httpStatusError
		if errors.As(err, &statusErr) && statusErr.status == http.StatusNotFound &&
			strings.HasPrefix(strings.ToLower(statusErr.message), repoNotFoundPrefix) {
			return nil, &RepoNotFoundError{
				Jurisdiction: jurisdiction,
				Repos:        parseNotFoundRepos(statusErr.message),
				Message:      statusErr.message,
			}
		}
		if errors.As(err, &statusErr) && statusErr.status == http.StatusNotFound && statusErr.message != "" {
			// The cell's other 404s ("no checkpoints in window", "no repos
			// covered") are already user-facing sentences.
			return nil, errors.New(statusErr.message)
		}
		return nil, err
	}
	return &out, nil
}

// GetDispatch reads a run by id from the cell of `jurisdiction` — which must be
// the jurisdiction it was created with, since a run lives in exactly one cell.
func (c *CloudClient) GetDispatch(ctx context.Context, id, jurisdiction string) (*DispatchDetail, error) {
	if strings.TrimSpace(id) == "" {
		return nil, errors.New("dispatch id is required")
	}
	var out DispatchDetail
	if err := c.doJSON(ctx, http.MethodGet, dispatchesPath+"/"+url.PathEscape(id), jurisdictionQuery(jurisdiction), nil, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// WaitForDispatch polls `detail` until it reaches a terminal status, sending
// the same jurisdiction selector the run was created with. A failed run is an
// error carrying the cell's reason.
func (c *CloudClient) WaitForDispatch(ctx context.Context, detail *DispatchDetail, jurisdiction string) (*DispatchDetail, error) {
	if detail == nil {
		return nil, errors.New("dispatch response was empty")
	}
	pollCtx, cancel := context.WithTimeout(ctx, dispatchPollTimeout)
	defer cancel()

	current := detail
	for {
		switch current.Status {
		case DispatchStatusComplete:
			return current, nil
		case DispatchStatusFailed:
			if current.ErrorMessage != nil && strings.TrimSpace(*current.ErrorMessage) != "" {
				return nil, fmt.Errorf("dispatch generation failed: %s", strings.TrimSpace(*current.ErrorMessage))
			}
			return nil, errors.New("dispatch generation failed")
		case DispatchStatusGenerating:
			// fall through to poll
		default:
			return nil, fmt.Errorf("unexpected dispatch status %q", current.Status)
		}
		if strings.TrimSpace(current.ID) == "" {
			return nil, errors.New("dispatch is still generating but the response carried no id to poll")
		}

		select {
		case <-pollCtx.Done():
			if errors.Is(pollCtx.Err(), context.DeadlineExceeded) && ctx.Err() == nil {
				return nil, fmt.Errorf("dispatch %s is still generating after %s; retry later", current.ID, dispatchPollTimeout)
			}
			return nil, fmt.Errorf("wait for dispatch: %w", pollCtx.Err())
		case <-time.After(dispatchPollInterval):
		}

		next, err := c.GetDispatch(pollCtx, current.ID, jurisdiction)
		if err != nil {
			return nil, err
		}
		current = next
	}
}

func jurisdictionQuery(jurisdiction string) url.Values {
	j := strings.TrimSpace(jurisdiction)
	if j == "" {
		return nil
	}
	return url.Values{jurisdictionQueryParam: []string{j}}
}

// parseNotFoundRepos pulls the slugs out of the cell's
// "repository not found: a/b, c/d" message. Best-effort: an unexpected format
// yields nil and the caller still has the message.
func parseNotFoundRepos(message string) []string {
	_, rest, ok := strings.Cut(message, ":")
	if !ok {
		return nil
	}
	var repos []string
	for _, part := range strings.Split(rest, ",") {
		if p := strings.TrimSpace(part); p != "" {
			repos = append(repos, p)
		}
	}
	return repos
}

func (c *CloudClient) doJSON(ctx context.Context, method, path string, query url.Values, reqBody, out any) error {
	var body io.Reader
	if reqBody != nil {
		data, err := json.Marshal(reqBody)
		if err != nil {
			return fmt.Errorf("marshal request body: %w", err)
		}
		body = bytes.NewReader(data)
	}

	target := c.baseURL + path
	if len(query) > 0 {
		target += "?" + query.Encode()
	}
	req, err := http.NewRequestWithContext(ctx, method, target, body)
	if err != nil {
		return fmt.Errorf("create request: %w", err)
	}
	req.Header.Set("Accept", "application/json")
	req.Header.Set("User-Agent", versioninfo.UserAgent())
	if reqBody != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if c.token != "" {
		req.Header.Set("Authorization", "Bearer "+c.token)
	}

	resp, err := c.http.Do(req)
	if err != nil {
		return fmt.Errorf("%s %s: %w", method, path, err)
	}
	defer resp.Body.Close()

	if resp.StatusCode == http.StatusUnauthorized {
		return errors.New("dispatch requires login — run `entire login`")
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		raw, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20)) //nolint:errcheck // best-effort body read for error message
		trimmed := strings.TrimSpace(string(raw))
		logging.Warn(ctx, "dispatch request failed", "method", method, "path", path, "status_code", resp.StatusCode)
		return &httpStatusError{status: resp.StatusCode, message: errorMessageFromBody(trimmed), raw: trimmed}
	}
	if out == nil {
		return nil
	}
	if err := json.NewDecoder(resp.Body).Decode(out); err != nil {
		return fmt.Errorf("decode response: %w", err)
	}
	return nil
}

// errorMessageFromBody extracts the human message from an error body in
// either the gateway's `{"error": "..."}` or huma's `{"detail": "..."}` shape.
// Non-JSON bodies yield "".
func errorMessageFromBody(body string) string {
	if body == "" {
		return ""
	}
	var parsed struct {
		Error   string `json:"error"`
		Detail  string `json:"detail"`
		Message string `json:"message"`
	}
	if err := json.Unmarshal([]byte(body), &parsed); err != nil {
		return ""
	}
	for _, candidate := range []string{parsed.Error, parsed.Detail, parsed.Message} {
		if c := strings.TrimSpace(candidate); c != "" {
			return c
		}
	}
	return ""
}

