func newTestCloudClient(t *testing.T, baseURL, token string) *CloudClient {
	t.Helper()
	transport := &http.Transport{DisableKeepAlives: true}
	t.Cleanup(transport.CloseIdleConnections)
	return NewCloudClient(CloudConfig{
		BaseURL: baseURL,
		Token:   token,
		HTTP: &http.Client{
			Transport: transport,
			Timeout:   defaultCloudHTTPTimeout,
		},
	})
}

// completeDispatchJSON is a terminal cell response in DispatchDetailWire shape.
func completeDispatchJSON(id, markdown string) string {
	return fmt.Sprintf(`{"id":%q,"setupId":"setup-1","status":"complete","title":null,"coveredRepos":["entireio/cli"],"coveredRepoUlids":["01X"],"branches":[],"voice":null,"window":{"normalizedSince":"2026-04-09T00:00:00Z","normalizedUntil":"2026-04-16T00:00:00Z","firstCheckpointCreatedAt":null,"lastCheckpointCreatedAt":null},"totals":{"checkpoints":1,"usedCheckpointCount":1,"branches":1,"filesTouched":2},"repos":[],"generatedMarkdown":%q,"isPersisted":true,"errorMessage":null,"createdAt":"2026-04-16T00:00:00Z","updatedAt":"2026-04-16T00:00:01Z","completedAt":"2026-04-16T00:00:01Z"}`, id, markdown)
}

func generatingDispatchJSON(id string) string {
	return fmt.Sprintf(`{"id":%q,"setupId":"setup-1","status":"generating","title":null,"coveredRepos":["entireio/cli"],"branches":[],"voice":null,"window":{"normalizedSince":"2026-04-09T00:00:00Z","normalizedUntil":"2026-04-16T00:00:00Z","firstCheckpointCreatedAt":null,"lastCheckpointCreatedAt":null},"totals":{"checkpoints":1,"usedCheckpointCount":1,"branches":1,"filesTouched":2},"repos":[],"generatedMarkdown":"","isPersisted":true,"errorMessage":null,"createdAt":"2026-04-16T00:00:00Z","updatedAt":"2026-04-16T00:00:00Z","completedAt":null}`, id)
}

// shortenDispatchPoll shrinks the package-level poll knobs for the duration of
// a test. Tests using it mutate shared state and must NOT call t.Parallel().
func shortenDispatchPoll(t *testing.T, interval, timeout time.Duration) {
	t.Helper()
	oldInterval, oldTimeout := dispatchPollInterval, dispatchPollTimeout
	dispatchPollInterval, dispatchPollTimeout = interval, timeout
	t.Cleanup(func() { dispatchPollInterval, dispatchPollTimeout = oldInterval, oldTimeout })
}

func TestCloudClient_CreateDispatch_Happy(t *testing.T) {
	t.Parallel()

	ctx := context.Background()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost || r.URL.Path != testDispatchEndpoint {
			http.NotFound(w, r)
			return
		}
		if r.Header.Get("Authorization") == "" {
			w.WriteHeader(http.StatusUnauthorized)
			return
		}
		if r.URL.Query().Has(jurisdictionQueryParam) {
			t.Errorf("home-jurisdiction request must not send a %s selector, got %q", jurisdictionQueryParam, r.URL.RawQuery)
		}

		var body map[string]any
		if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
			t.Error(err)
			return
		}
		repos, ok := body["repos"].([]any)
		if !ok || len(repos) != 1 || repos[0] != testRepoFullName {
			t.Errorf("bad repos payload: %v", body["repos"])
		}
		for _, forbidden := range []string{"repo", "wait", "generate", "branches", "orgs", "jurisdiction"} {
			if _, ok := body[forbidden]; ok {
				t.Errorf("did not expect %q in request body: %v", forbidden, body)
			}
		}

		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusAccepted)
		_, _ = w.Write([]byte(generatingDispatchJSON("run-1"))) //nolint:errcheck // test fixture response
	}))
	defer srv.Close()

	client := newTestCloudClient(t, srv.URL, "t")
	got, err := client.CreateDispatch(ctx, CreateDispatchRequest{
		Repos: []string{testRepoFullName},
		Since: "2026-04-09T00:00:00Z",
		Until: "2026-04-16T00:00:00Z",
	}, "")
	if err != nil {
		t.Fatal(err)
	}
	if got.ID != "run-1" || got.Status != DispatchStatusGenerating {
		t.Fatalf("unexpected detail: %+v", got)
	}
}

