func TestCloudClient_WaitForDispatch_PollsSameJurisdictionUntilComplete(t *testing.T) {
	shortenDispatchPoll(t, 5*time.Millisecond, 5*time.Second)

	var polls atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet || r.URL.Path != testDispatchEndpoint+"/run-7" {
			t.Errorf("unexpected poll %s %s", r.Method, r.URL.Path)
			http.NotFound(w, r)
			return
		}
		if got := r.URL.Query().Get(jurisdictionQueryParam); got != "au" {
			t.Errorf("poll must carry ?jurisdiction=au, got %q", r.URL.RawQuery)
		}
		w.Header().Set("Content-Type", "application/json")
		if polls.Add(1) < 3 {
			_, _ = w.Write([]byte(generatingDispatchJSON("run-7"))) //nolint:errcheck // test fixture response
			return
		}
		_, _ = w.Write([]byte(completeDispatchJSON("run-7", "done"))) //nolint:errcheck // test fixture response
	}))
	defer srv.Close()

	client := newTestCloudClient(t, srv.URL, "t")
	got, err := client.WaitForDispatch(context.Background(), &DispatchDetail{ID: "run-7", Status: DispatchStatusGenerating}, "au")
	if err != nil {
		t.Fatal(err)
	}
	if got.GeneratedMarkdown != "done" {
		t.Fatalf("unexpected final detail: %+v", got)
	}
	if polls.Load() != 3 {
		t.Fatalf("expected 3 polls, got %d", polls.Load())
	}
