func TestCloudClient_WaitForDispatch_TerminalStatuses(t *testing.T) {
	t.Parallel()

	client := newTestCloudClient(t, "http://unused.invalid", "t")
	ctx := context.Background()

	complete := &DispatchDetail{ID: "r", Status: DispatchStatusComplete, GeneratedMarkdown: "x"}
	got, err := client.WaitForDispatch(ctx, complete, "")
	if err != nil || got != complete {
		t.Fatalf("complete run should return immediately, got %v %v", got, err)
	}

	reason := "model timed out"
	_, err = client.WaitForDispatch(ctx, &DispatchDetail{ID: "r", Status: DispatchStatusFailed, ErrorMessage: &reason}, "")
	if err == nil || !strings.Contains(err.Error(), "dispatch generation failed: model timed out") {
		t.Fatalf("expected failed-run error with reason, got %v", err)
	}

	_, err = client.WaitForDispatch(ctx, &DispatchDetail{ID: "r", Status: DispatchStatusFailed}, "")
	if err == nil || err.Error() != "dispatch generation failed" {
		t.Fatalf("expected bare failed-run error, got %v", err)
	}

	_, err = client.WaitForDispatch(ctx, &DispatchDetail{ID: "r", Status: "weird"}, "")
	if err == nil || !strings.Contains(err.Error(), `unexpected dispatch status "weird"`) {
		t.Fatalf("expected unexpected-status error, got %v", err)
	}

	_, err = client.WaitForDispatch(ctx, &DispatchDetail{Status: DispatchStatusGenerating}, "")
	if err == nil || !strings.Contains(err.Error(), "no id to poll") {
		t.Fatalf("expected missing-id error, got %v", err)
	}

	if _, err := client.WaitForDispatch(ctx, nil, ""); err == nil {
		t.Fatal("expected error for nil detail")
	}
}

