package dispatch

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

// stubCloudDispatchAuth swaps the package-level auth/secure-URL hooks to
// produce a test token and bypass the HTTPS guard so tests can talk to a
// plain-HTTP httptest.NewServer. Tests that need to verify the HTTPS guard
// itself should not call this helper.
func stubCloudDispatchAuth(t *testing.T) {
	t.Helper()
	oldResource := lookupResourceToken
	oldRequire := requireSecureDispatchURL
	lookupResourceToken = func(_ context.Context, _ string) (string, error) {
		return testCloudDispatchToken, nil
	}
	requireSecureDispatchURL = func(string) error { return nil }
	t.Cleanup(func() {
		lookupResourceToken = oldResource
		requireSecureDispatchURL = oldRequire
	})
}

func freezeDispatchNow(t *testing.T) {
	t.Helper()
	oldNow := nowUTC
	nowUTC = func() time.Time { return time.Date(2026, 4, 16, 0, 0, 0, 0, time.UTC) }
	t.Cleanup(func() { nowUTC = oldNow })
}

// writeCompleteDispatch answers a POST with an already-complete run (the cell
// may return 200/201 when generation finished in-request).
func writeCompleteDispatch(t *testing.T, w http.ResponseWriter, coveredRepos []string, markdown string) {
	t.Helper()
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	if err := json.NewEncoder(w).Encode(map[string]any{
		"id":           "run-1",
		"setupId":      "setup-1",
		"status":       DispatchStatusComplete,
		"coveredRepos": coveredRepos,
		"branches":     []string{},
		"window": map[string]any{
			"normalizedSince": "2026-04-09T00:00:00Z",
			"normalizedUntil": "2026-04-16T00:00:00Z",
		},
		"totals": map[string]any{
			"checkpoints":         1,
			"usedCheckpointCount": 1,
			"branches":            1,
			"filesTouched":        0,
		},
		"repos":             []any{},
		"generatedMarkdown": markdown,
	}); err != nil {
		t.Error(err)
	}
}

func TestServerMode_HappyPath(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	testutil.WriteFile(t, dir, "a.txt", "x")
	testutil.GitAdd(t, dir, "a.txt")
	testutil.GitCommit(t, dir, "initial")
	addOriginRemote(t, dir)

	mock := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != testDispatchEndpoint {
			http.NotFound(w, r)
			return
		}
		if r.URL.Query().Has(jurisdictionQueryParam) {
			t.Errorf("no --jurisdiction means no selector (home), got query %q", r.URL.RawQuery)
		}

		var body map[string]any
		if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
			t.Error(err)
			return
		}
		repos, ok := body["repos"].([]any)
		if !ok || len(repos) != 1 || repos[0] != testRepoFullName {
			t.Errorf("unexpected repos payload: %v", body)
		}
		if _, ok := body["repo"]; ok {
			t.Errorf("did not expect repo payload: %v", body)
		}
		if body["until"] != "2026-04-15T18:30:00Z" {
			t.Errorf("unexpected until payload: %v", body["until"])
		}
		if _, ok := body["generate"]; ok {
			t.Errorf("the cell route has no generate flag: %v", body)
		}
		if _, ok := body["jurisdiction"]; ok {
			t.Errorf("jurisdiction must never be in the body: %v", body)
		}

		writeCompleteDispatch(t, w, []string{testRepoFullName}, testDispatchGeneratedHello)
	}))
	defer mock.Close()

	stubCloudDispatchAuth(t)
	freezeDispatchNow(t)

	t.Setenv("ENTIRE_API_BASE_URL", mock.URL)
	t.Chdir(dir)

	got, err := Run(context.Background(), Options{
		Mode:     ModeServer,
		Since:    "7d",
		Until:    "2026-04-15T18:30:00Z",
		Branches: []string{"main"},
		Voice:    "neutral",
	})
	if err != nil {
		t.Fatal(err)
	}
	if got.GeneratedText != testDispatchGeneratedHello {
		t.Fatalf("bad text: %q", got.GeneratedText)
	}
}

func TestServerMode_JurisdictionRoutesPostAndPollAlike(t *testing.T) {
	shortenDispatchPoll(t, 5*time.Millisecond, 5*time.Second)

	var polls atomic.Int32
	mock := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if got := r.URL.Query().Get(jurisdictionQueryParam); got != "eu" {
			t.Errorf("%s %s: expected ?jurisdiction=eu, got query %q", r.Method, r.URL.Path, r.URL.RawQuery)
		}
		switch {
		case r.Method == http.MethodPost && r.URL.Path == testDispatchEndpoint:
			var body map[string]any
			if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
				t.Error(err)
				return
			}
			if _, ok := body["jurisdiction"]; ok {
				t.Errorf("jurisdiction must never be in the body: %v", body)
			}
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusAccepted)
			_, _ = w.Write([]byte(generatingDispatchJSON("run-eu"))) //nolint:errcheck // test fixture response
		case r.Method == http.MethodGet && r.URL.Path == testDispatchEndpoint+"/run-eu":
			w.Header().Set("Content-Type", "application/json")
			if polls.Add(1) < 2 {
				_, _ = w.Write([]byte(generatingDispatchJSON("run-eu"))) //nolint:errcheck // test fixture response
				return
			}
			_, _ = w.Write([]byte(completeDispatchJSON("run-eu", testDispatchGeneratedHello))) //nolint:errcheck // test fixture response
		default:
			t.Errorf("unexpected request %s %s", r.Method, r.URL.Path)
			http.NotFound(w, r)
		}
	}))
	defer mock.Close()

	stubCloudDispatchAuth(t)
	freezeDispatchNow(t)
	t.Setenv("ENTIRE_API_BASE_URL", mock.URL)

	got, err := Run(context.Background(), Options{
		Mode:         ModeServer,
		RepoPaths:    []string{testRepoFullName},
		Since:        "7d",
		Jurisdiction: "eu",
	})
	if err != nil {
		t.Fatal(err)
	}
	if got.GeneratedText != testDispatchGeneratedHello {
		t.Fatalf("bad text: %q", got.GeneratedText)
	}
	if polls.Load() != 2 {
		t.Fatalf("expected 2 polls, got %d", polls.Load())
	}
}

func TestServerMode_RepoNotFoundNamesJurisdiction(t *testing.T) {
	mock := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != testDispatchEndpoint {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusNotFound)
		_, _ = w.Write([]byte(`{"error":"repository not found: entirehq/ferrata"}`)) //nolint:errcheck // test fixture response
	}))
	defer mock.Close()

	stubCloudDispatchAuth(t)
	freezeDispatchNow(t)
	t.Setenv("ENTIRE_API_BASE_URL", mock.URL)

	_, err := Run(context.Background(), Options{
		Mode:         ModeServer,
		RepoPaths:    []string{"entirehq/ferrata"},
		Since:        "7d",
		Jurisdiction: "au",
	})
	var notFound *RepoNotFoundError
	if !errors.As(err, &notFound) {
		t.Fatalf("expected *RepoNotFoundError, got %T: %v", err, err)
	}
	if notFound.Jurisdiction != "au" || !strings.HasPrefix(err.Error(), "In AU: repository not found: entirehq/ferrata.") {
		t.Fatalf("unexpected error: %v", err)
	}
}

func TestServerMode_FailedRunSurfacesReason(t *testing.T) {
	mock := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != testDispatchEndpoint {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"id":"run-x","status":"failed","errorMessage":"generation timed out","generatedMarkdown":""}`)) //nolint:errcheck // test fixture response
	}))
	defer mock.Close()

	stubCloudDispatchAuth(t)
	freezeDispatchNow(t)
	t.Setenv("ENTIRE_API_BASE_URL", mock.URL)

	_, err := Run(context.Background(), Options{
		Mode:      ModeServer,
		RepoPaths: []string{testRepoFullName},
		Since:     "7d",
	})
	if err == nil || err.Error() != "dispatch generation failed: generation timed out" {
		t.Fatalf("unexpected error: %v", err)
	}
}

func TestServerMode_ExplicitReposDoNotRequireCurrentRepo(t *testing.T) {
	mock := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != testDispatchEndpoint {
			http.NotFound(w, r)
			return
		}

		var body map[string]any
		if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
			t.Error(err)
			return
		}
		repos, ok := body["repos"].([]any)
		if !ok || len(repos) != 2 || repos[0] != testRepoFullName || repos[1] != "entireio/entire.io" {
			t.Errorf("unexpected repos payload: %v", body)
		}
		if _, ok := body["repo"]; ok {
			t.Errorf("did not expect repo payload: %v", body)
		}

		writeCompleteDispatch(t, w, []string{testRepoFullName, "entireio/entire.io"}, testDispatchGeneratedHello)
	}))
	defer mock.Close()

	stubCloudDispatchAuth(t)
	freezeDispatchNow(t)

	t.Setenv("ENTIRE_API_BASE_URL", mock.URL)

	got, err := Run(context.Background(), Options{
		Mode:      ModeServer,
		RepoPaths: []string{testRepoFullName, "entireio/entire.io"},
		Since:     "7d",
	})
	if err != nil {
		t.Fatal(err)
	}
	if got == nil {
		t.Fatal("expected dispatch result")
	}
	if len(got.CoveredRepos) != 2 {
		t.Fatalf("expected covered repos to propagate, got %v", got.CoveredRepos)
	}
}

func TestAPIToDispatch_DerivesRepoURLs(t *testing.T) {
	t.Parallel()

	first := "2026-04-10T00:00:00Z"
	got := apiToDispatch(&DispatchDetail{
		Window: APIWindow{
			NormalizedSince:          "2026-04-09T00:00:00Z",
			NormalizedUntil:          "2026-04-16T00:00:00Z",
			FirstCheckpointCreatedAt: &first,
		},
		CoveredRepos: []string{testRepoFullName},
		Repos: []APIRepo{{
			FullName: testRepoFullName,
			Sections: []APISection{{Label: "Shipped", Bullets: []APIBullet{{CheckpointID: testCheckpointID, Text: "x", CreatedAt: first, Labels: []string{"feat"}}}}},
		}},
		GeneratedMarkdown: "  hi  ",
	})
	if len(got.Repos) != 1 || got.Repos[0].URL != testRepoURL {
		t.Fatalf("expected repo URL derived from full name, got %+v", got.Repos)
	}
	if got.Repos[0].Sections[0].Bullets[0].CheckpointID != testCheckpointID {
		t.Fatalf("expected bullets mapped, got %+v", got.Repos[0].Sections)
	}
	if got.Window.FirstCheckpointAt.IsZero() || !got.Window.LastCheckpointAt.IsZero() {
		t.Fatalf("unexpected window: %+v", got.Window)
	}
	if got.GeneratedText != "hi" {
		t.Fatalf("expected trimmed markdown, got %q", got.GeneratedText)
	}
	if apiToDispatch(nil) == nil {
		t.Fatal("nil detail should map to an empty dispatch")
	}
}

func TestServerMode_RequiresGeneratedMarkdown(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	testutil.WriteFile(t, dir, "a.txt", "x")
	testutil.GitAdd(t, dir, "a.txt")
	testutil.GitCommit(t, dir, "initial")
	addOriginRemote(t, dir)

	mock := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != testDispatchEndpoint {
			http.NotFound(w, r)
			return
		}
		writeCompleteDispatch(t, w, []string{testRepoFullName}, "")
	}))
	defer mock.Close()

	stubCloudDispatchAuth(t)
	freezeDispatchNow(t)

	t.Setenv("ENTIRE_API_BASE_URL", mock.URL)
	t.Chdir(dir)

	_, err := Run(context.Background(), Options{
		Mode:  ModeServer,
		Since: "7d",
	})
	if err == nil {
		t.Fatal("expected error when server response omits generated markdown")
	}
	if err.Error() != "dispatch generation returned no markdown" {
		t.Fatalf("unexpected error: %v", err)
	}
}

func TestServerMode_NormalizesWindowAndSanitizesVoice(t *testing.T) {
	mock := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != testDispatchEndpoint {
			http.NotFound(w, r)
			return
		}

		var body map[string]any
		if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
			t.Error(err)
			return
		}
		if body["since"] != "2026-04-09T00:00:00Z" {
			t.Errorf("unexpected normalized since payload: %v", body["since"])
		}
		if body["until"] != "2026-04-16T00:01:00Z" {
			t.Errorf("unexpected normalized until payload: %v", body["until"])
		}
		voice, ok := body["voice"].(string)
		if !ok {
			t.Errorf("expected voice string payload, got %T", body["voice"])
		}
		if voice != "calm\nand steady" {
			t.Errorf("unexpected sanitized voice payload: %q", voice)
		}

		writeCompleteDispatch(t, w, []string{testRepoFullName}, testDispatchGeneratedHello)
	}))
	defer mock.Close()

	stubCloudDispatchAuth(t)

	t.Setenv("ENTIRE_API_BASE_URL", mock.URL)

	got, err := Run(context.Background(), Options{
		Mode:      ModeServer,
		RepoPaths: []string{testRepoFullName},
		Since:     "2026-04-09T00:00:29Z",
		Until:     "2026-04-16T00:00:31Z",
		Voice:     " calm�\nand‮ steady​ ",
	})
	if err != nil {
		t.Fatal(err)
	}
	if got.GeneratedText != testDispatchGeneratedHello {
		t.Fatalf("unexpected generated text: %q", got.GeneratedText)
	}
}

// TestServerMode_InsecureHTTPAuthBypassesSecureURLCheck confirms that setting
// Options.InsecureHTTPAuth=true skips the real requireSecureDispatchURL check
// and lets dispatch talk to an http:// base URL. This is the local-dev escape
// hatch that matches the --insecure-http-auth flag on login/trail. The test
// deliberately does not stub requireSecureDispatchURL — the flag alone must
// bypass the guard.
func TestServerMode_InsecureHTTPAuthBypassesSecureURLCheck(t *testing.T) {
	mock := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != testDispatchEndpoint {
			http.NotFound(w, r)
			return
		}
		writeCompleteDispatch(t, w, []string{testRepoFullName}, testDispatchGeneratedHello)
	}))
	defer mock.Close()

	oldResource := lookupResourceToken
	lookupResourceToken = func(_ context.Context, _ string) (string, error) {
		return testCloudDispatchToken, nil
	}
	t.Cleanup(func() { lookupResourceToken = oldResource })
	freezeDispatchNow(t)

	t.Setenv("ENTIRE_API_BASE_URL", mock.URL)

	got, err := Run(context.Background(), Options{
		Mode:             ModeServer,
		RepoPaths:        []string{testRepoFullName},
		Since:            "7d",
		InsecureHTTPAuth: true,
	})
	if err != nil {
		t.Fatalf("expected insecure override to bypass the HTTPS guard, got %v", err)
	}
	if got.GeneratedText != testDispatchGeneratedHello {
		t.Fatalf("unexpected generated text: %q", got.GeneratedText)
	}
}

// TestServerMode_RejectsPlainHTTPBaseURL pins the production guarantee that
// bearer tokens are never sent to an http:// base URL. It deliberately does
// not call stubCloudDispatchAuth — the real requireSecureDispatchURL must
// fire. If a future refactor drops the check, this test breaks before the
// leak reaches users.
func TestServerMode_RejectsPlainHTTPBaseURL(t *testing.T) {
	oldResource := lookupResourceToken
	lookupResourceToken = func(_ context.Context, _ string) (string, error) {
		return testCloudDispatchToken, nil
	}
	t.Cleanup(func() { lookupResourceToken = oldResource })

	t.Setenv("ENTIRE_API_BASE_URL", "http://dispatch.example.invalid")

	_, err := Run(context.Background(), Options{
		Mode:      ModeServer,
		RepoPaths: []string{testRepoFullName},
		Since:     "7d",
	})
	if err == nil {
		t.Fatal("expected error when dispatch base URL is http://")
	}
	if !strings.Contains(err.Error(), api.ErrInsecureHTTP.Error()) {
		t.Fatalf("expected ErrInsecureHTTP, got %v", err)
	}
}

